        const rulesSnap = await getDocs(collection(db, "supportAutoAssignRules"));
        setAutoAssignRules(rulesSnap.docs.map(d => ({ id: d.id, ...d.data() })));
        
        // Fetch SLA settings
        const slaDoc = await getDoc(doc(db, "supportSettings", "sla"));
